import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { springIn, drawPath, ambientDrift } from "../motion";

export const fps = 25;
export const durationInFrames = 446;

// ============================================================================
// BLOCK 3 — "Dashboard views + filter slices"
// A BI dashboard assembles panel-by-panel (2x2 grid of real charts), then a
// filter chip row appears and the dashboard visibly responds to filtering.
// ============================================================================

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};
const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_MONO = "monospace";

// RGB triples for smooth color blends
const RGB = {
  orange: [248, 102, 6],
  orangeDeep: [255, 72, 0],
  gray: [140, 147, 168], // textSubtle
  muted: [191, 193, 197], // textMuted
  borderC: [61, 63, 67],
};

// ---- cues (exact) ----
const CUE = { p1: 0, p2: 38, p3: 84, p4: 141 };

// ---- helpers ----
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const ci = (f: number, inp: number[], out: number[]) =>
  interpolate(f, inp, out, { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
const mix = (a: number[], b: number[], t: number) =>
  `rgb(${Math.round(lerp(a[0], b[0], t))},${Math.round(lerp(a[1], b[1], t))},${Math.round(lerp(a[2], b[2], t))})`;

// ---- chart data ----
const LOC = {
  labels: ["NYC", "LA", "CHI", "MIA", "SEA", "AUS"],
  vals: [0.82, 0.9, 0.74, 0.86, 0.5, 0.78], // idx4 = weak location
  sel: [0, 1, 2], // location-filter subset (stays bright)
  opsIdx: 1, // ops-view highlighted region
};
const ZONE = {
  labels: ["Z1", "Z2", "Z3", "Z4"],
  you: [0.8, 0.64, 0.9, 0.7],
  comp: [0.6, 0.72, 0.55, 0.66],
  opsIdx: 2,
};
const PRICE = {
  yours: [0.5, 0.56, 0.52, 0.6, 0.58, 0.66, 0.63],
  market: [0.56, 0.5, 0.58, 0.5, 0.62, 0.55, 0.67],
};
const SENT = [0.3, 0.42, 0.5, 0.62, 0.7, 0.76, 0.79, 0.8];

// ============================================================================
// PANEL 1 — Ratings · location : vertical bars, one weak
// ============================================================================
function BarsLocation(props: {
  frame: number;
  fps: number;
  w: number;
  h: number;
  locSel: number;
  opsF: number;
}) {
  const { frame, fps, w, h, locSel, opsF } = props;
  const pad = { l: w * 0.03, r: w * 0.03, t: h * 0.09, b: h * 0.17 };
  const baseline = h - pad.b;
  const plotH = baseline - pad.t;
  const plotW = w - pad.l - pad.r;
  const n = LOC.vals.length;
  const slot = plotW / n;
  const bw = slot * 0.5;
  const rx = bw * 0.16;

  return (
    <svg width={w} height={h} style={{ display: "block", overflow: "visible" }}>
      {[0.25, 0.5, 0.75].map((g) => (
        <line
          key={g}
          x1={pad.l}
          y1={pad.t + g * plotH}
          x2={w - pad.r}
          y2={pad.t + g * plotH}
          stroke={COLORS.border}
          strokeOpacity={0.5}
          strokeWidth={1}
        />
      ))}
      <line x1={pad.l} y1={baseline} x2={w - pad.r} y2={baseline} stroke={COLORS.border} strokeWidth={1.5} />
      {LOC.vals.map((v, i) => {
        const c = CUE.p1 + 2 + i * 3;
        const grow = ci(frame, [c, c + 18], [0, v]);
        const bh = grow * plotH;
        const x = pad.l + slot * i + (slot - bw) / 2;
        const y = baseline - bh;
        const selected = LOC.sel.includes(i);
        const isOps = i === LOC.opsIdx;
        let op = selected ? 1 : lerp(1, 0.3, locSel);
        op *= isOps ? 1 : lerp(1, 0.16, opsF);
        const fill = mix(RGB.orange, RGB.orangeDeep, isOps ? opsF : 0);
        return (
          <g key={i}>
            <rect x={x} y={y} width={bw} height={bh} rx={rx} fill={fill} opacity={op} />
            <text
              x={x + bw / 2}
              y={h - pad.b * 0.42}
              textAnchor="middle"
              fill={COLORS.textSubtle}
              fontSize={h * 0.06}
              fontFamily={FONT_MONO}
              opacity={op * 0.9 + 0.1}
            >
              {LOC.labels[i]}
            </text>
          </g>
        );
      })}
    </svg>
  );
}

// ============================================================================
// PANEL 2 — Competitor · zone : grouped bars (you vs competitor)
// ============================================================================
function BarsCompetitor(props: {
  frame: number;
  fps: number;
  w: number;
  h: number;
  opsF: number;
}) {
  const { frame, w, h, opsF } = props;
  const pad = { l: w * 0.03, r: w * 0.03, t: h * 0.09, b: h * 0.17 };
  const baseline = h - pad.b;
  const plotH = baseline - pad.t;
  const plotW = w - pad.l - pad.r;
  const n = ZONE.labels.length;
  const slot = plotW / n;
  const bw = slot * 0.24;
  const gap = slot * 0.05;
  const rx = bw * 0.16;

  return (
    <svg width={w} height={h} style={{ display: "block", overflow: "visible" }}>
      {[0.25, 0.5, 0.75].map((g) => (
        <line
          key={g}
          x1={pad.l}
          y1={pad.t + g * plotH}
          x2={w - pad.r}
          y2={pad.t + g * plotH}
          stroke={COLORS.border}
          strokeOpacity={0.5}
          strokeWidth={1}
        />
      ))}
      <line x1={pad.l} y1={baseline} x2={w - pad.r} y2={baseline} stroke={COLORS.border} strokeWidth={1.5} />
      {ZONE.labels.map((lab, z) => {
        const cx = pad.l + slot * z + slot / 2;
        const yc = CUE.p2 + 2 + z * 4;
        const cc = CUE.p2 + 5 + z * 4;
        const yg = ci(frame, [yc, yc + 18], [0, ZONE.you[z]]);
        const cg = ci(frame, [cc, cc + 18], [0, ZONE.comp[z]]);
        const isOps = z === ZONE.opsIdx;
        const youOp = isOps ? 1 : lerp(1, 0.2, opsF);
        const compOp = lerp(1, 0.24, opsF);
        const youFill = mix(RGB.orange, RGB.orangeDeep, isOps ? opsF : 0);
        const yh = yg * plotH;
        const ch = cg * plotH;
        const xYou = cx - gap / 2 - bw;
        const xComp = cx + gap / 2;
        return (
          <g key={z}>
            <rect x={xYou} y={baseline - yh} width={bw} height={yh} rx={rx} fill={youFill} opacity={youOp} />
            <rect x={xComp} y={baseline - ch} width={bw} height={ch} rx={rx} fill={COLORS.textSubtle} opacity={compOp} />
            <text
              x={cx}
              y={h - pad.b * 0.42}
              textAnchor="middle"
              fill={COLORS.textSubtle}
              fontSize={h * 0.06}
              fontFamily={FONT_MONO}
            >
              {lab}
            </text>
          </g>
        );
      })}
    </svg>
  );
}

// ============================================================================
// PANEL 3 — Price index : two lines + area fill (yours vs market)
// ============================================================================
function PriceLines(props: {
  frame: number;
  fps: number;
  w: number;
  h: number;
  opsF: number;
  priceF: number;
}) {
  const { frame, fps, w, h, opsF, priceF } = props;
  const pad = { l: w * 0.035, r: w * 0.035, t: h * 0.12, b: h * 0.14 };
  const baseline = h - pad.b;
  const plotH = baseline - pad.t;
  const plotW = w - pad.l - pad.r;
  const n = PRICE.yours.length;
  const px = (i: number) => pad.l + (i / (n - 1)) * plotW;
  const py = (v: number) => baseline - v * plotH;

  const yoursPts = PRICE.yours.map((v, i) => ({ x: px(i), y: py(v) }));
  const mktPts = PRICE.market.map((v, i) => ({ x: px(i), y: py(v) }));
  const line = (pts: { x: number; y: number }[]) =>
    pts.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(" ");
  const yoursLine = line(yoursPts);
  const mktLine = line(mktPts);
  const areaPath = `${yoursLine} L ${px(n - 1).toFixed(1)} ${baseline.toFixed(1)} L ${px(0).toFixed(1)} ${baseline.toFixed(1)} Z`;

  const prog = clamp01(springIn(frame, fps, CUE.p3, "LIQUID"));
  const revealW = pad.l + plotW * prog + 4;
  const yoursStroke = mix(RGB.orange, RGB.orangeDeep, opsF);
  const areaOp = lerp(0.14, 0.28, priceF);
  const mktOp = ci(opsF, [0, 1], [1, 0.22]);
  const sw = h * 0.01;

  return (
    <svg width={w} height={h} style={{ display: "block", overflow: "visible" }}>
      <defs>
        <clipPath id="p3clip">
          <rect x={0} y={0} width={revealW} height={h} />
        </clipPath>
      </defs>
      {[0.25, 0.5, 0.75].map((g) => (
        <line
          key={g}
          x1={pad.l}
          y1={pad.t + g * plotH}
          x2={w - pad.r}
          y2={pad.t + g * plotH}
          stroke={COLORS.border}
          strokeOpacity={0.5}
          strokeWidth={1}
        />
      ))}
      <line x1={pad.l} y1={baseline} x2={w - pad.r} y2={baseline} stroke={COLORS.border} strokeWidth={1.5} />
      <g clipPath="url(#p3clip)">
        <path d={areaPath} fill={COLORS.orange} opacity={areaOp} />
        <path
          d={mktLine}
          fill="none"
          stroke={COLORS.textSubtle}
          strokeWidth={sw}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={`${h * 0.03} ${h * 0.02}`}
          opacity={mktOp}
        />
        <path
          d={yoursLine}
          fill="none"
          stroke={yoursStroke}
          strokeWidth={sw * 1.15}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </g>
      {yoursPts.map((p, i) => {
        const reveal = prog * (n - 1) - i;
        const dotOp = ci(reveal, [0, 0.5], [0, 1]);
        return <circle key={i} cx={p.x} cy={p.y} r={h * 0.014} fill={yoursStroke} opacity={dotOp} />;
      })}
    </svg>
  );
}

// ============================================================================
// PANEL 4 — Sentiment trend : line drawing on, node dots pop
// ============================================================================
function SentimentLine(props: {
  frame: number;
  fps: number;
  w: number;
  h: number;
  opsF: number;
}) {
  const { frame, fps, w, h, opsF } = props;
  const pad = { l: w * 0.035, r: w * 0.035, t: h * 0.12, b: h * 0.14 };
  const baseline = h - pad.b;
  const plotH = baseline - pad.t;
  const plotW = w - pad.l - pad.r;
  const n = SENT.length;
  const pts = SENT.map((v, i) => ({
    x: pad.l + (i / (n - 1)) * plotW,
    y: baseline - v * plotH,
  }));
  const path = pts.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(" ");
  let len = 0;
  for (let i = 1; i < pts.length; i++) len += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
  const draw = drawPath(frame, fps, len, { delay: CUE.p4, preset: "LIQUID" });
  const prog = clamp01(springIn(frame, fps, CUE.p4, "LIQUID"));
  const stroke = mix(RGB.orange, RGB.orangeDeep, opsF);
  const sw = h * 0.011;

  return (
    <svg width={w} height={h} style={{ display: "block", overflow: "visible" }}>
      {[0.25, 0.5, 0.75].map((g) => (
        <line
          key={g}
          x1={pad.l}
          y1={pad.t + g * plotH}
          x2={w - pad.r}
          y2={pad.t + g * plotH}
          stroke={COLORS.border}
          strokeOpacity={0.5}
          strokeWidth={1}
        />
      ))}
      <line x1={pad.l} y1={baseline} x2={w - pad.r} y2={baseline} stroke={COLORS.border} strokeWidth={1.5} />
      <path
        d={path}
        fill="none"
        stroke={stroke}
        strokeWidth={sw}
        strokeLinecap="round"
        strokeLinejoin="round"
        {...draw}
      />
      {pts.map((p, i) => {
        const reveal = prog * (n - 1) - i;
        const dotOp = ci(reveal, [0, 0.5], [0, 1]);
        return <circle key={i} cx={p.x} cy={p.y} r={h * 0.013} fill={stroke} opacity={dotOp} />;
      })}
    </svg>
  );
}

// ============================================================================
// PANEL SHELL
// ============================================================================
function PanelShell(props: {
  frame: number;
  fps: number;
  base: number;
  cue: number;
  seed: number;
  title: string;
  w: number;
  h: number;
  pad: number;
  titleH: number;
  titleGap: number;
  panelMult: number;
  panelScale: number;
  legend?: { color: string; dashed?: boolean; label: string }[];
  children: React.ReactNode;
}) {
  const { frame, fps, base, cue, seed, title, w, h, pad, titleH, titleGap, panelMult, panelScale, legend, children } = props;
  // Panels are present from frame 0 (no opacity fade-in). They still settle in
  // with a subtle translate, but never start invisible.
  const inn = springIn(frame, fps, cue, "LIQUID");
  const ty = interpolate(inn, [0, 1], [26, 0]);
  const drift = ambientDrift(frame, 1.2, 130, seed);
  return (
    <div
      style={{
        width: w,
        height: h,
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: base * 0.014,
        padding: pad,
        boxSizing: "border-box",
        opacity: clamp01(panelMult),
        transform: `translateY(${ty + drift}px) scale(${panelScale})`,
        boxShadow: "0 10px 30px rgba(0,0,0,0.35)",
      }}
    >
      <div style={{ height: titleH, display: "flex", alignItems: "center", gap: base * 0.008 }}>
        <div style={{ width: base * 0.009, height: base * 0.009, borderRadius: base * 0.002, background: COLORS.orange }} />
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontWeight: 600,
            fontSize: base * 0.019,
            color: COLORS.text,
            letterSpacing: "-0.01em",
          }}
        >
          {title}
        </div>
        <div style={{ flex: 1 }} />
        {legend &&
          legend.map((lg, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: base * 0.004, marginLeft: base * 0.01 }}>
              <div
                style={{
                  width: base * 0.014,
                  height: lg.dashed ? 0 : base * 0.007,
                  borderTop: lg.dashed ? `2px dashed ${lg.color}` : undefined,
                  background: lg.dashed ? undefined : lg.color,
                  borderRadius: 2,
                }}
              />
              <div style={{ fontFamily: FONT_MONO, fontSize: base * 0.011, color: COLORS.textSubtle }}>{lg.label}</div>
            </div>
          ))}
      </div>
      <div style={{ height: titleGap }} />
      <div style={{ width: w - pad * 2, height: h - pad * 2 - titleH - titleGap }}>{children}</div>
    </div>
  );
}

// ============================================================================
// FILTER CHIP
// ============================================================================
function Chip(props: { frame: number; fps: number; base: number; cue: number; act: number; label: string }) {
  const { frame, fps, base, cue, act, label } = props;
  const inn = springIn(frame, fps, cue, "SNAPPY");
  const sc = interpolate(inn, [0, 1], [0.82, 1]);
  const bd = mix(RGB.borderC, RGB.orange, act);
  const tc = mix(RGB.muted, RGB.orange, act);
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: base * 0.006,
        padding: `${base * 0.011}px ${base * 0.018}px`,
        borderRadius: base * 0.05,
        border: `1.5px solid ${bd}`,
        background: `rgba(248,102,6,${(0.16 * act).toFixed(3)})`,
        opacity: clamp01(inn),
        transform: `scale(${sc})`,
      }}
    >
      <div
        style={{
          width: base * 0.007,
          height: base * 0.007,
          borderRadius: "50%",
          background: mix(RGB.gray, RGB.orange, act),
        }}
      />
      <div style={{ fontFamily: FONT_MARKETING, fontWeight: 600, fontSize: base * 0.016, color: tc, letterSpacing: "-0.005em" }}>
        {label}
      </div>
    </div>
  );
}

// ============================================================================
// MAIN
// ============================================================================
const Block3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // ---- container geometry ----
  const cW = width * 0.82;
  const cH = height * 0.86;
  const cPad = base * 0.024;
  const innerW = cW - cPad * 2;
  const innerH = cH - cPad * 2;
  const headerH = base * 0.05;
  const chipRowH = base * 0.055;
  const g1 = base * 0.014;
  const g2 = base * 0.018;
  const gridGap = base * 0.016;
  const gridH = innerH - headerH - chipRowH - g1 - g2;
  const panelW = (innerW - gridGap) / 2;
  const panelH = (gridH - gridGap) / 2;

  const pPad = base * 0.02;
  const titleH = base * 0.026;
  const titleGap = base * 0.01;
  const chartW = panelW - pPad * 2;
  const chartH = panelH - pPad * 2 - titleH - titleGap;

  // ---- phase factors ----
  const locSel = ci(frame, [187, 205], [0, 1]);
  const opsF = ci(frame, [306, 324], [0, 1]);
  const priceF = ci(frame, [337, 358], [0, 1]);

  // ---- chip activation ----
  const actLocation = ci(frame, [192, 206], [0, 1]);
  const actZone = ci(frame, [306, 320], [0, 1]);
  const actPlatform = ci(frame, [337, 351], [0, 1]);

  // ---- panel-level emphasis ----
  const softLoc = lerp(1, 0.92, locSel);
  const pricingDim = lerp(1, 0.34, priceF);
  const multP1 = pricingDim;
  const multP2 = softLoc * pricingDim;
  const multP3 = softLoc; // price panel: not dimmed by pricing view
  const multP4 = softLoc * pricingDim;
  const scaleP3 = lerp(1, 1.035, priceF);

  // ---- container: present from frame 0, subtle settle only (no opacity fade) ----
  const contIn = springIn(frame, vfps, 0, "LIQUID");
  const contTy = interpolate(contIn, [0, 1], [24, 0]);
  const contDrift = ambientDrift(frame, 1.2, 150, "cont");

  return (
    <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          width: cW,
          height: cH,
          background: COLORS.bg,
          border: `1px solid ${COLORS.border}`,
          borderRadius: base * 0.02,
          padding: cPad,
          boxSizing: "border-box",
          display: "flex",
          flexDirection: "column",
          transform: `translateY(${contTy + contDrift}px)`,
          boxShadow: "0 30px 80px rgba(0,0,0,0.55)",
        }}
      >
        {/* ---- header ---- */}
        <div style={{ height: headerH, display: "flex", alignItems: "center", gap: base * 0.014 }}>
          <div
            style={{
              width: base * 0.036,
              height: base * 0.036,
              borderRadius: base * 0.009,
              background: COLORS.orange,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <div style={{ width: base * 0.016, height: base * 0.016, borderRadius: base * 0.003, background: COLORS.bg }} />
          </div>
          <div
            style={{
              fontFamily: FONT_MARKETING,
              fontWeight: 600,
              fontSize: base * 0.026,
              color: COLORS.text,
              letterSpacing: "-0.02em",
            }}
          >
            Market Intelligence
          </div>
          <div style={{ flex: 1 }} />
          <div style={{ display: "flex", alignItems: "center", gap: base * 0.007 }}>
            <div style={{ width: base * 0.008, height: base * 0.008, borderRadius: "50%", background: COLORS.orange }} />
            <div style={{ fontFamily: FONT_MONO, fontSize: base * 0.014, color: COLORS.textSubtle, letterSpacing: "0.06em" }}>
              Q3 · LIVE
            </div>
          </div>
        </div>
        <div style={{ height: g1 }} />

        {/* ---- filter chip row ---- */}
        <div style={{ height: chipRowH, display: "flex", alignItems: "center", gap: base * 0.012 }}>
          <div
            style={{
              fontFamily: FONT_MONO,
              fontSize: base * 0.013,
              color: COLORS.textSubtle,
              letterSpacing: "0.1em",
              textTransform: "uppercase",
              marginRight: base * 0.004,
            }}
          >
            Filters
          </div>
          <Chip frame={frame} fps={vfps} base={base} cue={187} act={actLocation} label="Location" />
          <Chip frame={frame} fps={vfps} base={base} cue={229} act={actZone} label="Zone" />
          <Chip frame={frame} fps={vfps} base={base} cue={235} act={0} label="Date range" />
          <Chip frame={frame} fps={vfps} base={base} cue={262} act={actPlatform} label="Platform" />
        </div>
        <div style={{ height: g2 }} />

        {/* ---- 2x2 grid ---- */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `${panelW}px ${panelW}px`,
            gridTemplateRows: `${panelH}px ${panelH}px`,
            gap: gridGap,
          }}
        >
          <PanelShell
            frame={frame}
            fps={vfps}
            base={base}
            cue={CUE.p1}
            seed={11}
            title="Ratings · location"
            w={panelW}
            h={panelH}
            pad={pPad}
            titleH={titleH}
            titleGap={titleGap}
            panelMult={multP1}
            panelScale={1}
          >
            <BarsLocation frame={frame} fps={vfps} w={chartW} h={chartH} locSel={locSel} opsF={opsF} />
          </PanelShell>

          <PanelShell
            frame={frame}
            fps={vfps}
            base={base}
            cue={CUE.p2}
            seed={22}
            title="Competitor · zone"
            w={panelW}
            h={panelH}
            pad={pPad}
            titleH={titleH}
            titleGap={titleGap}
            panelMult={multP2}
            panelScale={1}
            legend={[
              { color: COLORS.orange, label: "You" },
              { color: COLORS.textSubtle, label: "Comp" },
